import html,json,statistics,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];OUT=HERE/(sys.argv[1] if len(sys.argv)>1 else 'results')
sys.path.insert(0,str(ROOT/'benchmarks/fixed-budget'))
import report as previous
r=json.loads((OUT/'attempts.json').read_text());assert len(r)==10
summary={}
for v in ['baseline','optimized']:
 rows=[x for x in r if x['variant']==v]
 summary[v]={'successes':sum(x['success'] for x in rows),'attempts':len(rows),
 'median_time_s':statistics.median(x['duration_s'] for x in rows if x['success']),
 'median_peak_mib':statistics.median(x['peak_rss_bytes']['harness']/2**20 for x in rows),
 'max_peak_mib':max(x['peak_rss_bytes']['harness']/2**20 for x in rows),
 'mean_input_tokens':statistics.mean(x['input_tokens'] for x in rows),
 'mean_output_tokens':statistics.mean(x['output_tokens'] for x in rows),
 'mean_tool_calls':statistics.mean(x['tool_calls'] for x in rows)}
matched=[a for a in range(1,6) if all(x['success'] for x in r if x['attempt']==a)]
for v in summary:summary[v]['matched_median_s']=statistics.median(x['duration_s'] for x in r if x['variant']==v and x['attempt'] in matched) if matched else None
s=json.loads((OUT/'state.json').read_text());d={'summary':summary,'matched_attempts':matched,'runs':r,'state':s}
(OUT/'report-data.json').write_text(json.dumps(d,indent=2))
b,o=summary.values()
reductions={k:100*(1-o[k]/b[k]) for k in ['median_peak_mib','matched_median_s','mean_input_tokens','mean_output_tokens','mean_tool_calls']}
metrics=[('Verified fixes','successes',' / 5'),('Completion time (matched median)','matched_median_s',' s'),('Harness memory (median peak)','median_peak_mib',' MiB'),('Harness memory (highest peak)','max_peak_mib',' MiB'),('Input tokens (mean)','mean_input_tokens',''),('Output tokens (mean)','mean_output_tokens',''),('Tool calls (mean)','mean_tool_calls','')]
rows=''.join(f'<tr><td>{label}</td><td>{b[k]:,.1f}{unit}</td><td>{o[k]:,.1f}{unit}</td></tr>' for label,k,unit in metrics)
records=''.join(f'<tr><td>{x["attempt"]}.{x["position"]}</td><td>{x["variant"]}</td><td>{"Pass" if x["success"] else "Fail"}</td><td>{x["duration_s"]:.1f}s</td><td>{x["peak_rss_bytes"]["harness"]/2**20:.1f} MiB</td><td>{x["input_tokens"]:,} / {x["output_tokens"]:,}</td><td>{x["tool_calls"]}</td><td><a href="benchmarks/optimization/{OUT.name}/{x["log"]}.diff">diff</a> · <a href="benchmarks/optimization/{OUT.name}/{x["log"]}.verify.stdout">checks</a></td></tr>' for x in r)
css=previous.TEMPLATE.split('<style>',1)[1].split('</style>',1)[0]
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Handwork efficiency validation</title><style>{css} .panel{{min-width:0}}</style><main><header><div class="brand">handwork.</div><span class="badge">EFFICIENCY VALIDATION</span></header><div class="hero"><div class="tag">Frozen Handwork versus updated Handwork</div><h1>Same bug. Fewer steps. Measured memory.</h1><p class="intro">Updated Handwork completed {o['successes']} of 5 attempts; baseline Handwork completed {b['successes']} of 5, with {reductions['median_peak_mib']:.1f}% less median peak harness memory in the updated build. This paired pilot checks the search race fix with nine independent groups and unchanged protected files.</p><div class="meta"><span>GPT-6 Astra · low reasoning</span><span>Five alternating pairs</span><span>300 seconds per attempt</span></div></div><section class="panel"><h2>Measured comparison</h2><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Frozen baseline</th><th>Updated Handwork</th></tr></thead><tbody>{rows}</tbody></table></div><p class="small">Timing uses {len(matched)} matched successful pairs. Token and tool averages include all attempts. RSS is sampled using the same harness/test/tool classification. Small differences are subject to sampling and service variability.</p></section><section class="panel"><h2>What changed</h2><p>Related replacements use one atomic edit against the original file. Independent reads are requested together through existing tools. The final revision limits read-only execution to two concurrent tools. The base prompt and repeated path descriptions are shorter; small-fix summaries and supplemental checks are kept concise. Cache and reasoning usage are exposed separately without changing total token accounting.</p><p>No sidecar, new model agent, connection pool, or additional runtime dependency was introduced. Batch edits retain existing permission, freshness, review and commit checks; the final file is allocated once.</p></section><section class="panel"><h2>All ten attempts</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Build</th><th>Result</th><th>Time</th><th>Harness peak</th><th>Input / output</th><th>Tools</th><th>Evidence</th></tr></thead><tbody>{records}</tbody></table></div></section><section class="panel"><h2>Protocol and limitations</h2><p>Every fresh workspace starts at {html.escape(s['commit'])}. Both builds use the exact original task prompt, model, reasoning setting, sandbox, five-minute budget and hidden verifier. The local HTTP server was paused during scoring. The verifier uses controlled promises and checks API, controller and view behavior.</p><p>This is five pairs on one small fixture, not proof that memory or speed will stay identical for every workload. Hosted model hardware, cache routing and service load are uncontrolled. Full JSON includes separate test/tool process peaks, raw usage, checks and binary hashes.</p><p>Validation: 163 focused Zig tests and two accounting tests passed. Thirty unrelated full-suite failures reproduced on both original and updated source; the full suite is not claimed clean. Logs are retained with the results.</p><details><summary>Binary hashes</summary><pre>{html.escape(json.dumps(s['variants'],indent=2))}</pre></details></section><footer><a href="handwork-optimization-initial.html">Initial revision (all runs retained)</a><a href="benchmarks/optimization/implementation.diff">Implementation diff</a><a href="benchmarks/optimization/{OUT.name}/report-data.json">Raw results JSON</a><a href="search-benchmark-results.html">Three-harness search benchmark (corrected accounting)</a></footer></main></html>'''
if OUT.name == 'results-final':
 from current_report import render
 page = render(css)
(ROOT/('handwork-optimization-initial.html' if OUT.name=='results' else 'handwork-optimization-results.html')).write_text(page)
print(json.dumps({'summary':summary,'reductions_pct':reductions},indent=2))
